"""Publish the acoustic renderer's evidence and two authored genre kits."""
from pathlib import Path
import argparse,hashlib,json,shutil,subprocess
p=argparse.ArgumentParser();p.add_argument('evidence',type=Path);p.add_argument('dist',type=Path);a=p.parse_args();out=a.dist/'acoustic-engine-5';out.mkdir(exist_ok=True)
def audio(source,name):
 dest=out/(name+'.flac');subprocess.run(['ffmpeg','-v','error','-y','-i',str(source),'-c:a','flac',str(dest)],check=True)
 return f'<audio controls preload="none" src="acoustic-engine-5/{dest.name}"></audio>'
style='''*{box-sizing:border-box}body{margin:0;background:#f4f0e6;color:#233b3b;font:17px/1.6 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:32px 20px 70px}header{border-top:5px solid #21665f;padding-top:24px}h1{font-size:clamp(48px,9vw,88px);line-height:1.02;letter-spacing:-.06em;margin:20px 0}h2{margin-top:44px;font-size:28px}h3{margin:0 0 10px}a{color:#21665f;text-underline-offset:4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}article{background:#fffdf7;border:1px solid #c9d2c8;padding:20px;border-radius:6px}audio{width:100%;margin:8px 0}small,.hint{font-size:14px}.download{display:inline-block;background:#21665f;color:#fff;padding:10px 16px;border-radius:4px;border:0;font:inherit;cursor:pointer}footer{border-top:1px solid #c9d2c8;padding-top:22px;margin-top:40px}a:focus-visible,button:focus-visible{outline:3px solid #ad733c;outline-offset:4px}'''
parts=[]
for ident,title,desc in [('backwash-soul','Soul Pocket','94 BPM. Tight drums, cross-stick backbeats, ghost notes and tambourine.'),('backwash-psych','Psych Rock','108 BPM. Open drums, a brighter cowbell pattern and ringing ride bell.')]:
 src=a.evidence/(ident+'.zip');data=src.read_bytes();sha=hashlib.sha256(data).hexdigest()
 if len(data)<24*1024*1024:
  shutil.copy2(src,out/src.name);download=f'<a class="download" download href="acoustic-engine-5/{src.name}">Download {title} · {len(data)/1e6:.0f} MB</a>'
 else:
  urls=[]
  for i,start in enumerate(range(0,len(data),8*1024*1024)):
   name=f'{ident}.part{i+1}';(out/name).write_bytes(data[start:start+8*1024*1024]);urls.append('acoustic-engine-5/'+name)
  manifest={'parts':urls,'sha256':sha,'bytes':len(data),'name':src.name};(out/(ident+'.json')).write_text(json.dumps(manifest))
  download=f'<button class="download" data-download="acoustic-engine-5/{ident}.json">Download {title} · {len(data)/1e6:.0f} MB</button><span role="status"></span>'
 parts.append(f'<article><h3>{title}</h3><p>{desc}</p>'+audio(a.evidence/ident/'groove.wav',ident+'-groove')+download+'</article>')
comparisons=[]
for ident,title in [('cross_stick','Cross-stick'),('cowbell','Cowbell'),('tambourine','Tambourine'),('ride','Ride bell')]:
 comparisons.append(f'<article><h3>{title}</h3><small>Dry acoustic strike</small>'+audio(a.evidence/(ident+'-dry.wav'),ident+'-dry')+'<small>Chorus → compression → parallel amp</small>'+audio(a.evidence/(ident+'-processed.wav'),ident+'-processed')+'</article>')
script='''document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})},true);document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{const s=b.nextElementSibling;b.disabled=true;try{const m=await(await fetch(b.dataset.download)).json(),chunks=[];for(let i=0;i<m.parts.length;i++){s.textContent=` Preparing part ${i+1}/${m.parts.length}…`;const r=await fetch(m.parts[i]);if(!r.ok)throw Error('Download interrupted');chunks.push(new Uint8Array(await r.arrayBuffer()))}const bytes=new Uint8Array(chunks.reduce((n,c)=>n+c.length,0));let off=0;chunks.forEach(c=>{bytes.set(c,off);off+=c.length});const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(bytes.length!==m.bytes||hash!==m.sha256)throw Error('Checksum mismatch');const u=URL.createObjectURL(new Blob([bytes],{type:'application/zip'})),a=document.createElement('a');a.href=u;a.download=m.name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);s.textContent=' Download verified.'}catch(e){s.textContent=' '+e.message+'. Please try again.'}finally{b.disabled=false}});'''
index=a.dist/'index.html';old=a.dist/'processing-study.html'
if not old.exists():shutil.copy2(index,old)
index.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BACKWASH · Acoustic engine</title><style>'+style+'</style></head><body><main><header><small>SNIPSNAP / BACKWASH / ACOUSTIC ENGINE 5</small><h1>Real strikes.<br>Moving sound.</h1><p>The acoustic cross-stick, cowbell, tambourine and ride bell are now inside BACKWASH. Recorded dynamics and alternate strikes feed the chorus, compressor and amp. The core drums keep the earlier sound.</p></header><h2>Two kits, two musical roles</h2><p>Sixteen pads each, with velocity layers, cycling takes and tambourine roll/riser pads. These grooves play the saved kit grids.</p><div class="grid">'+''.join(parts)+'</div><p class="hint">Unzip the kit and keep its folders together. In MPC 3, open the .xtd file. The included MPC 2 .xpm plays the first take of each velocity layer; MPC 2 does not cycle this bank. Hardware playback still needs auditioning.</p><h2>Hear the source through the chain</h2><p>The same recorded strike on each side. Dry bypasses the effects. Processed uses the new default treatment; levels are not loudness matched. Natural room sound stays in the recording, and the ride keeps its full tail.</p><div class="grid">'+''.join(comparisons)+'</div><h2>Play it in SnipSnap</h2><p>Choose BACKWASH in the engine picker, or BACKWASH SOUL / BACKWASH PSYCH on the starter shelf. Earlier saved recipes retain their original renderer.</p><p><a class="download" href="kit-and-phone.html#phone-preview">Get the Android preview</a></p><details><summary>What has been checked</summary><p>Recorded take selection and saved recipes, save/reopen of both 16-pad grids, offline playback cycling, and MPC 3 cycle fields are checked. Android and instrumentation APKs are compiled; on-device tests and MPC hardware audition remain outstanding. These are engine integration results, not a declaration that every acceptance gate is complete.</p><p>Cross-stick uses four adjacent recorded velocity strikes per group, across four groups; these were not recorded as dedicated round robins. Cowbell uses 3 × 7 takes, ride bell 3 × 3, and tambourine 2 × 2. Procedural core drums use generated variation.</p></details><footer><p>Acoustic recordings: Virtuosity Drums / Versilian Studios, Austin McMahon; VSCO 2 CE, Sam Gossner, Simon Dalzell, Elan Hickler. CC0 sources with pinned provenance.</p><a href="processing-study.html">Earlier processing studies and dry source audition</a> · <a href="acoustic-sources-1/manifest.json">Source manifest</a></footer></main><script>'+script+'</script></body></html>')
print('Built acoustic-engine audition page')
